#include "World/BloodstreamWorldRegistry.h"
namespace { FBloodstreamEntityId Id(const TCHAR* S){ FBloodstreamEntityId Out; ensure(FBloodstreamEntityId::TryParse(S,Out)); return Out; }
const TArray<FBloodstreamRegionDefinition> GRegions=[](){ TArray<FBloodstreamRegionDefinition>A; FBloodstreamRegionDefinition R; R.RegionId=Id(TEXT("10000000-0000-0000-0000-000000000001"));R.InternalName=TEXT("LindstripeBasin");R.DisplayName=FText::FromString(TEXT("Lindstripe Basin"));R.Biome=EBloodstreamBiome::Basin;R.JurisdictionProfile=TEXT("Lindstripe");R.EnvironmentProfile=TEXT("BasinTemperateVariable");R.EncounterProfile=TEXT("LindstripeEarlyAdult");R.Center=FVector::ZeroVector;R.Extent=FVector(600000,500000,100000);A.Add(R);return A;}();
const TArray<FBloodstreamLandmarkDefinition> GLandmarks=[](){TArray<FBloodstreamLandmarkDefinition>A; const auto R=GRegions[0].RegionId; struct D{const TCHAR*Id;const TCHAR*N;EBloodstreamLandmarkType T;FVector P;float I;float V;}; D Df[]={
{TEXT("20000000-0000-0000-0000-000000000001"),TEXT("LindstripeTownSilhouette"),EBloodstreamLandmarkType::Settlement,FVector(0,0,0),1,6},
{TEXT("20000000-0000-0000-0000-000000000002"),TEXT("BasinMineHeadframe"),EBloodstreamLandmarkType::Mine,FVector(-220000,160000,25000),1,8},
{TEXT("20000000-0000-0000-0000-000000000003"),TEXT("EasternRailWaterTower"),EBloodstreamLandmarkType::Rail,FVector(180000,20000,0),.8f,5},
{TEXT("20000000-0000-0000-0000-000000000004"),TEXT("NorthDarkRidge"),EBloodstreamLandmarkType::Ridge,FVector(-50000,380000,70000),1,15},
{TEXT("20000000-0000-0000-0000-000000000005"),TEXT("CreekConfluence"),EBloodstreamLandmarkType::Water,FVector(60000,-90000,-5000),.7f,2},
{TEXT("20000000-0000-0000-0000-000000000006"),TEXT("WesternBasinPass"),EBloodstreamLandmarkType::Pass,FVector(-520000,30000,45000),.9f,10}}; for(const auto&X:Df){FBloodstreamLandmarkDefinition L;L.LandmarkId=Id(X.Id);L.RegionId=R;L.InternalName=X.N;L.Type=X.T;L.ApproximateLocation=X.P;L.NavigationImportance=X.I;L.IntendedVisibilityKm=X.V;A.Add(L);}return A;}();
const TArray<FBloodstreamRoadDefinition> GRoads=[](){TArray<FBloodstreamRoadDefinition>A; const auto R=GRegions[0].RegionId; struct D{const TCHAR*Id;const TCHAR*N;EBloodstreamRoadClass C;FVector S,E;bool W;};D Df[]={
{TEXT("30000000-0000-0000-0000-000000000001"),TEXT("WestPassToLindstripe"),EBloodstreamRoadClass::Primary,FVector(-520000,30000,0),FVector(0,0,0),true},
{TEXT("30000000-0000-0000-0000-000000000002"),TEXT("LindstripeMineRoad"),EBloodstreamRoadClass::IndustrialAccess,FVector(0,0,0),FVector(-220000,160000,0),true},
{TEXT("30000000-0000-0000-0000-000000000003"),TEXT("SouthCreekTrail"),EBloodstreamRoadClass::Trail,FVector(0,0,0),FVector(60000,-250000,0),false},
{TEXT("30000000-0000-0000-0000-000000000004"),TEXT("EasternRailServiceRoad"),EBloodstreamRoadClass::Secondary,FVector(0,0,0),FVector(430000,30000,0),true}};for(const auto&X:Df){FBloodstreamRoadDefinition V;V.RoadId=Id(X.Id);V.RegionId=R;V.InternalName=X.N;V.RoadClass=X.C;V.Start=X.S;V.End=X.E;V.bFutureWagonEligible=X.W;A.Add(V);}return A;}(); }
const TArray<FBloodstreamRegionDefinition>& FBloodstreamWorldRegistry::Regions(){return GRegions;} const TArray<FBloodstreamLandmarkDefinition>& FBloodstreamWorldRegistry::Landmarks(){return GLandmarks;} const TArray<FBloodstreamRoadDefinition>& FBloodstreamWorldRegistry::Roads(){return GRoads;}
const FBloodstreamRegionDefinition* FBloodstreamWorldRegistry::FindRegion(const FVector&P){return GRegions.FindByPredicate([&](const auto&R){return R.Contains(P);});}
bool FBloodstreamWorldRegistry::Validate(FString& Error){TSet<FBloodstreamEntityId>Ids;for(const auto&R:GRegions){if(!R.RegionId.IsValid()||Ids.Contains(R.RegionId)){Error=TEXT("Invalid/duplicate region ID");return false;}Ids.Add(R.RegionId);}TSet<FBloodstreamEntityId>LIds;for(const auto&L:GLandmarks){if(!L.LandmarkId.IsValid()||LIds.Contains(L.LandmarkId)){Error=TEXT("Invalid/duplicate landmark ID");return false;}LIds.Add(L.LandmarkId);if(!GRegions.ContainsByPredicate([&](const auto&R){return R.RegionId==L.RegionId;})){Error=TEXT("Landmark has unknown region");return false;}}TSet<FBloodstreamEntityId>RoadIds;for(const auto&V:GRoads){if(!V.RoadId.IsValid()||RoadIds.Contains(V.RoadId)){Error=TEXT("Invalid/duplicate road ID");return false;}RoadIds.Add(V.RoadId);if(!GRegions.ContainsByPredicate([&](const auto&R){return R.RegionId==V.RegionId;})){Error=TEXT("Road has unknown region");return false;}}return true;}
